#include <cstdio>
#include <string>
#include <iostream>

int main() {
    std::string s, t;
    std::getline(std::cin, s);
    std::getline(std::cin, t);
    if (s.size() != t.size()) { printf("NO\n"); return 0; }

    int cnt[256] = {0};
    for (unsigned char c : s) cnt[c]++;
    for (unsigned char c : t) cnt[c]--;
    bool ok = true;
    for (int i = 0; i < 256; ++i) if (cnt[i] != 0) { ok = false; break; }
    printf("%s\n", ok ? "YES" : "NO");
    return 0;
}
